'use strict';
// The input file is generated by Python through actual G3b, never fake API fixture JSON.
const {test} = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const p = require('../../prototypes/h2-workbench/presentation.js');
const bundle = JSON.parse(fs.readFileSync(process.argv[2], 'utf8'));
const clone = () => structuredClone(bundle);

test('actual backend envelope accepted without mutation', () => {
  const copy = clone(); assert.equal(p.validate(copy), copy); assert.deepEqual(copy, bundle);
});
for (const locale of ['zh-CN', 'en-US']) {
  test(`${locale} authorized identities counts and pages preserved`, () => {
    const before = clone(), view = p.view(before, 'iris', 'initial', 2, locale);
    assert.equal(view.offset, 4); assert.equal(view.lanes[0].total, 5);
    assert.equal(view.lanes[0].rows.length, 1); assert.equal(view.lanes[0].hasMore, false);
    assert.deepEqual(before, bundle);
  });
  test(`${locale} private fields absent for the other peer`, () => {
    for (const page of [0, 1]) assert.ok(!JSON.stringify(p.view(bundle, 'soren', 'initial', page, locale)).includes('h2-iris-private'));
  });
  test(`${locale} source and publication revocation remain independent`, () => {
    const source = p.view(bundle, 'iris', 'source-revoked', 0, locale);
    assert.equal(source.lanes[0].total, 3); assert.equal(source.lanes[2].total, 1);
    const publication = p.view(bundle, 'iris', 'publication-revoked', 0, locale);
    assert.equal(publication.lanes[0].total, 3); assert.equal(publication.lanes[2].total, 0);
  });
  test(`${locale} observation scope never infers Safety`, () => {
    const view = p.view(bundle, 'iris', 'observation-only', 0, locale);
    assert.equal(view.lanes[1].total, 0); assert.equal(view.lanes[0].total, 3);
    for (const row of view.lanes[0].rows) assert.ok(!Object.hasOwn(row, 'safety'));
  });
  test(`${locale} unknown is not clear and steps are not accepted tasks`, () => {
    assert.match(p.text(locale, 'unknown-not-clear'), locale === 'zh-CN' ? /不能视为安全/ : /not cleared/);
    const row = p.view(bundle, 'iris', 'initial', 0, locale).lanes[2].rows[0];
    assert.deepEqual(Object.keys(row), ['identifier', 'label']);
    assert.match(p.text(locale, 'step-warning'), locale === 'zh-CN' ? /不是已接受待办/ : /not an accepted task/);
  });
}
const invalid = [
  b => {b.schema = 'old';}, b => {b.token = 'hidden';}, b => {b.synthetic_only = 1;},
  b => {b.scenarios[0].peers[0].pages[0].schema = 'other';},
  b => {delete b.scenarios[0].peers[0].pages[0].security;},
  b => {b.scenarios[0].peers[0].pages[0].observations.items[0].safety = 'declared-clear';},
  b => {b.scenarios[0].peers[0].pages[0].security.items[0].safety = 'safe';},
  b => {b.scenarios[0].peers[0].pages[0].published_steps.items[0].status = 'accepted';},
  b => {b.scenarios[0].peers[0].pages[0].observations.items[0].source_id = '<img src=x>';},
  b => {b.scenarios[0].peers[0].pages[1].pagination.offset = 0;},
  b => {b.scenarios[0].peers[0].pages.pop();},
  b => {b.scenarios[0].peers[0].pages[1].observations.total = 6;},
];
invalid.forEach((mutate, n) => test(`malformed scope/page/envelope ${n} rejects all partial display`, () => {
  const b = clone(); mutate(b); assert.throws(() => p.view(b, 'iris', 'initial', 0, 'zh-CN'));
}));
test('unknown locale, peer, phase or page rejected without identity authority', () => {
  for (const args of [['unknown','initial',0,'zh-CN'], ['iris','not-recorded',0,'zh-CN'],
                      ['iris','initial',3,'zh-CN'], ['iris','initial',0,'unknown']]) assert.throws(() => p.view(bundle, ...args));
});
